import copyWithin = require( './index' );


// TESTS //

// The function returns a collection...
{
	const arr = [ 1, 2, 3, 4, 5 ];
	copyWithin( arr, 0, 3 ); // $ExpectType Collection<number>

	const typedArr = new Int8Array( [ 1, 2, 3, 4, 5 ] );
	copyWithin( typedArr, 0, 3 ); // $ExpectType Collection<number>
}

// The compiler throws an error if the function is provided a first argument which is not a collection...
{
	copyWithin( 5, 0 ); // $ExpectError
	copyWithin( true, 0 ); // $ExpectError
	copyWithin( false, 0 ); // $ExpectError
	copyWithin( null, 0 ); // $ExpectError
	copyWithin( undefined, 0 ); // $ExpectError
	copyWithin( {}, 0 ); // $ExpectError
}

// The compiler throws an error if the function is provided a second argument which is not a number...
{
	const arr = [ 1, 2, 3, 4, 5 ];
	copyWithin( arr, '5' ); // $ExpectError
	copyWithin( arr, true ); // $ExpectError
	copyWithin( arr, false ); // $ExpectError
	copyWithin( arr, [] ); // $ExpectError
	copyWithin( arr, {} ); // $ExpectError
	copyWithin( arr, ( x: number ): number => x ); // $ExpectError
}

// The compiler throws an error if the function is provided a third argument which is not a number...
{
	const arr = [ 1, 2, 3, 4, 5 ];
	copyWithin( arr, 0, '5' ); // $ExpectError
	copyWithin( arr, 0, true ); // $ExpectError
	copyWithin( arr, 0, false ); // $ExpectError
	copyWithin( arr, 0, [] ); // $ExpectError
	copyWithin( arr, 0, {} ); // $ExpectError
	copyWithin( arr, 0, ( x: number ): number => x ); // $ExpectError
}

// The compiler throws an error if the function is provided a fourth argument which is not a number...
{
	const arr = [ 1, 2, 3, 4, 5 ];
	copyWithin( arr, 0, 0, '5' ); // $ExpectError
	copyWithin( arr, 0, 0, true ); // $ExpectError
	copyWithin( arr, 0, 0, false ); // $ExpectError
	copyWithin( arr, 0, 0, [] ); // $ExpectError
	copyWithin( arr, 0, 0, {} ); // $ExpectError
	copyWithin( arr, 0, 0, ( x: number ): number => x ); // $ExpectError
}

// The compiler throws an error if the function is provided an invalid number of arguments...
{
	copyWithin(); // $ExpectError
	copyWithin( [ 1, 2, 3 ] ); // $ExpectError
	copyWithin( [ 1, 2, 3 ], 0, 0, 1, 2 ); // $ExpectError
}
